//! Independent analytic fixtures and adversarial checks for the canonical mesh.
//! A planar fixture is generated by solving each post's ellipsoidal height
//! for a prescribed ECEF X plane; expected intersections do not use the
//! production triangle intersection routine.

use earth_math::{
    CameraFrame, EnuBasis, Geodetic, Lens, Observer, PatchTextureView, Projection, Ray,
    SurfaceKind, TerrainError, TerrainPatch, TerrainScene, TextureProjection, TextureView, Vec3d,
    WGS84_A_M, WGS84_E2, geodetic_to_ecef,
};

fn geo(lat: f64, lon: f64, height: f64) -> Geodetic {
    Geodetic::new(lat, lon, height).unwrap()
}

fn close(actual: f64, expected: f64, tolerance: f64) {
    assert!(
        actual.is_finite() && (actual - expected).abs() <= tolerance,
        "actual={actual:.17e}, expected={expected:.17e}, tolerance={tolerance:.17e}"
    );
}

fn plane_height(latitude: f64, longitude: f64, plane_x: f64) -> f64 {
    let phi = latitude.to_radians();
    let lambda = longitude.to_radians();
    let n = WGS84_A_M / (1.0 - WGS84_E2 * phi.sin().powi(2)).sqrt();
    plane_x / (phi.cos() * lambda.cos()) - n
}

fn plane_patch(plane_x: f64) -> TerrainPatch {
    let mut heights = Vec::new();
    for row in 0..=10 {
        for column in 0..=10 {
            heights.push(plane_height(
                0.1 - f64::from(row) * 0.02,
                -0.1 + f64::from(column) * 0.02,
                plane_x,
            ));
        }
    }
    TerrainPatch::from_grid(11, 11, -0.1, 0.1, 0.02, 0.02, heights).unwrap()
}

#[test]
fn planar_mesh_has_analytic_distance_and_outward_normal() {
    let plane_x = WGS84_A_M + 120.0;
    let patch = plane_patch(plane_x);
    assert_eq!(patch.vertex_count(), 121);
    assert_eq!(patch.triangle_count(), 200);
    let distance = 10_000.0 * 1.0725_f64.sqrt();
    for scale in [1.0e-200, 0.01, 1.0, 17.0, 1.0e200] {
        let ray = Ray {
            origin: Vec3d::new(plane_x + 10_000.0, 0.0, 0.0),
            direction: Vec3d::new(-1.0, 0.25, 0.1) * scale,
        };
        let hit = patch.intersect(ray).unwrap();
        close(hit.distance_m, distance, 2.0e-8);
        close(hit.position.x, plane_x, 3.0e-9);
        close(hit.position.y, 2500.0, 1.0e-8);
        close(hit.position.z, 1000.0, 1.0e-8);
        close(hit.normal.x, 1.0, 1.0e-12);
        close(hit.normal.y, 0.0, 1.0e-12);
        close(hit.normal.z, 0.0, 1.0e-12);
    }
}

#[test]
fn terrain_ray_is_double_sided_and_rejects_parallel_or_backward_hits() {
    let plane_x = WGS84_A_M + 120.0;
    let patch = plane_patch(plane_x);
    let from_below = patch
        .intersect(Ray {
            origin: Vec3d::new(plane_x - 20.0, 0.0, 0.0),
            direction: Vec3d::new(3.0, 0.0, 0.0),
        })
        .unwrap();
    close(from_below.distance_m, 20.0, 3.0e-9);
    for direction in [
        Vec3d::new(0.0, 1.0, 0.0),
        Vec3d::new(1.0, 0.0, 0.0),
        Vec3d::ZERO,
        Vec3d::new(f64::NAN, 0.0, 0.0),
    ] {
        assert!(
            patch
                .intersect(Ray {
                    origin: Vec3d::new(plane_x + 20.0, 0.0, 0.0),
                    direction,
                })
                .is_none()
        );
    }
}

#[test]
fn shared_edges_and_vertices_do_not_leak() {
    let plane_x = WGS84_A_M + 120.0;
    let patch = plane_patch(plane_x);
    for row in 1..10 {
        for column in 1..10 {
            let latitude = 0.1 - f64::from(row) * 0.02;
            let longitude = -0.1 + f64::from(column) * 0.02;
            let a = geodetic_to_ecef(geo(
                latitude,
                longitude,
                plane_height(latitude, longitude, plane_x),
            ));
            let b = geodetic_to_ecef(geo(
                latitude,
                longitude + 0.02,
                plane_height(latitude, longitude + 0.02, plane_x),
            ));
            for target in [a, (a + b) * 0.5] {
                for displacement in [Vec3d::new(100.0, 0.0, 0.0), Vec3d::new(1.0, 50.0, -13.0)] {
                    let hit = patch
                        .intersect(Ray {
                            origin: target + displacement,
                            direction: -displacement,
                        })
                        .expect("shared vertex/edge must be covered");
                    close(hit.distance_m, displacement.length(), 2.0e-7);
                }
            }
        }
    }
}

#[test]
fn below_ellipsoid_terrain_replaces_baseline_and_sets_real_ground_height() {
    let scene = TerrainScene::new(vec![plane_patch(WGS84_A_M - 500.0)]);
    let ray = Ray {
        origin: Vec3d::new(WGS84_A_M + 1000.0, 0.0, 0.0),
        direction: Vec3d::new(-1.0, 0.0, 0.0),
    };
    let hit = scene.intersect(ray).unwrap();
    assert_eq!(hit.kind, SurfaceKind::Terrain(0));
    close(hit.hit.distance_m, 1500.0, 3.0e-9);
    close(hit.hit.geodetic.height_m, -500.0, 3.0e-9);
    let mut observer = Observer::new(geo(0.0, 0.0, 0.0));
    scene
        .place_on_ground(&mut observer, geo(0.0, 0.0, 10_000.0))
        .unwrap();
    close(observer.feet.height_m, -500.0, 3.0e-9);
    let ground = scene
        .intersect(CameraFrame::new(observer.eye_geodetic(), 0.0, -90.0).center_ray())
        .unwrap();
    close(ground.hit.distance_m, observer.eye_height_m, 4.0e-9);
    let outside = CameraFrame::new(geo(0.0, 5.0, 1000.0), 0.0, -90.0).center_ray();
    assert_eq!(
        scene.intersect(outside).unwrap().kind,
        SurfaceKind::ReferenceEllipsoid
    );
}

#[test]
fn exact_teleport_rejects_subterranean_coordinates_without_mutation() {
    let scene = TerrainScene::new(vec![plane_patch(WGS84_A_M + 120.0)]);
    let mut observer = Observer::new(geo(0.0, 0.0, 200.0));
    let initial = observer.feet;
    assert_eq!(
        scene.try_teleport(&mut observer, geo(0.0, 0.0, 100.0)),
        Err(TerrainError::BelowSurface)
    );
    assert_eq!(observer.feet, initial);
    let accepted = geo(0.0012345, -0.0045678, 200.123456789);
    scene.try_teleport(&mut observer, accepted).unwrap();
    assert_eq!(observer.feet, accepted);
    let negative = TerrainScene::new(vec![plane_patch(WGS84_A_M - 500.0)]);
    negative
        .try_teleport(&mut observer, geo(0.0, 0.0, -499.0))
        .unwrap();
    assert_eq!(observer.feet, geo(0.0, 0.0, -499.0));
}

#[test]
fn terrain_collision_stops_fast_downward_flight_without_tunneling() {
    for surface_height in [-500.0, 120.0] {
        let scene = TerrainScene::new(vec![plane_patch(WGS84_A_M + surface_height)]);
        let mut observer = Observer::new(geo(0.0, 0.0, surface_height + 1000.0));
        observer.pitch_deg = -90.0;
        observer.speed_mps = 50_000_000.0;
        scene.fly(&mut observer, 1.0, 0.0, 0.0, 0.25, true);
        close(observer.feet.height_m, surface_height + 0.00001, 1.0e-7);
        scene
            .place_on_ground(&mut observer, geo(0.0, 0.0, 0.0))
            .unwrap();
        observer.pitch_deg = -90.0;
        observer.speed_mps = 50_000_000.0;
        let before = observer.feet;
        scene.fly(&mut observer, 1.0, 0.0, 0.0, 0.25, true);
        assert_eq!(observer.feet, before);
    }
}

#[test]
fn bvh_matches_brute_force_for_rough_surface_and_grazing_rays() {
    let width = 23;
    let height = 19;
    let mut heights = Vec::new();
    for row in 0..height {
        for column in 0..width {
            let value = 300.0 + ((row * 13 + column * 29) % 37) as f64 * 17.0;
            heights.push(value);
        }
    }
    let patch = TerrainPatch::from_grid(width, height, -0.11, 0.09, 0.01, 0.01, heights).unwrap();
    let mut state = 0xa9e5_d38c_70b1_624d_u64;
    let mut random = || {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        (state >> 11) as f64 / ((1_u64 << 53) as f64)
    };
    for _ in 0..1200 {
        let location = geo(
            (random() - 0.5) * 0.22,
            (random() - 0.5) * 0.26,
            1000.0 + random() * 10_000.0,
        );
        let basis = EnuBasis::at(location);
        let direction = -basis.up * random().powi(3)
            + basis.east * (random() - 0.5)
            + basis.north * (random() - 0.5);
        let ray = Ray {
            origin: geodetic_to_ecef(location),
            direction,
        };
        let accelerated = patch.intersect(ray);
        let reference = patch.intersect_brute_force(ray);
        assert_eq!(accelerated.is_some(), reference.is_some());
        if let (Some(a), Some(b)) = (accelerated, reference) {
            close(a.distance_m, b.distance_m, 1.0e-8);
            assert!(a.position.distance(b.position) < 1.0e-8);
        }
    }
}

#[test]
fn rendered_center_and_range_select_the_same_below_ellipsoid_mesh() {
    let scene = TerrainScene::new(vec![plane_patch(WGS84_A_M - 500.0)]);
    let frame = CameraFrame::new(geo(0.0, 0.0, 1000.0), 0.0, -90.0);
    let global = [255, 0, 0, 255];
    let local = [0, 255, 0, 255];
    let texture = PatchTextureView {
        texture: TextureView {
            rgba: &local,
            width: 1,
            height: 1,
        },
        projection: TextureProjection::Geographic,
        west_deg: -0.1,
        south_deg: -0.1,
        east_deg: 0.1,
        north_deg: 0.1,
    };
    for lens in [
        Lens::default(),
        Lens::new(Projection::EquidistantFisheye, 140.0),
        Lens::new(Projection::Rectilinear, 0.001),
    ] {
        let hit = scene.intersect(frame.center_ray()).unwrap();
        close(hit.hit.distance_m, 1500.0, 3.0e-9);
        let color = scene.render_pixel(
            frame,
            lens,
            0,
            0,
            1,
            1,
            [1440.0, 900.0],
            Some(TextureView {
                rgba: &global,
                width: 1,
                height: 1,
            }),
            &[Some(texture)],
        );
        assert_eq!(color[0], 0);
        assert!(color[1] > 0);
        assert_eq!(color[2], 0);
    }
}

#[test]
fn invalid_or_incomplete_grid_is_not_silently_flattened() {
    assert!(TerrainPatch::from_grid(1, 2, 0.0, 1.0, 0.01, 0.01, vec![0.0; 2]).is_err());
    assert!(TerrainPatch::from_grid(2, 2, 0.0, 1.0, 0.01, 0.01, vec![0.0; 3]).is_err());
    assert!(
        TerrainPatch::from_grid(2, 2, 0.0, 1.0, 0.01, 0.01, vec![0.0, f64::NAN, 0.0, 0.0]).is_err()
    );
    assert!(TerrainPatch::from_grid(2, 2, 0.0, 1.0, 0.01, 0.01, vec![-32767.0; 4]).is_err());
    assert!(TerrainPatch::from_bytes(b"AETERR01").is_err());
}

#[test]
fn geometric_coverage_has_no_hole_between_southern_boundary_posts() {
    let plane_x = geodetic_to_ecef(geo(35.0, 0.0, 120.0)).x;
    let mut heights = Vec::new();
    for row in 0..3 {
        for column in 0..3 {
            heights.push(plane_height(
                35.01 - f64::from(row) * 0.01,
                -0.01 + f64::from(column) * 0.01,
                plane_x,
            ));
        }
    }
    let patch = TerrainPatch::from_grid(3, 3, -0.01, 35.01, 0.01, 0.01, heights).unwrap();
    let location = geo(34.99, -0.005, 0.0);
    assert!(patch.contains(location));
    let scene = TerrainScene::new(vec![patch]);
    let hit = scene
        .ground(location)
        .expect("coverage transitions must resolve to terrain or explicit fallback");
    let sight = scene
        .intersect(CameraFrame::new(geo(34.99, -0.005, 10_000.0), 0.0, -90.0).center_ray())
        .unwrap();
    assert_eq!(sight.kind, hit.kind);
    close(
        sight.hit.distance_m,
        10_000.0 - hit.hit.geodetic.height_m,
        1.0e-7,
    );
}

#[test]
fn far_ellipsoid_intersection_remains_visible_after_masked_near_intersection() {
    let scene = TerrainScene::new(vec![plane_patch(WGS84_A_M - 500.0)]);
    let origin = Vec3d::new(WGS84_A_M + 10.0, -1000.0, 0.0);
    let direction = Vec3d::new(-0.005, 1.0, 0.0).normalized().unwrap();
    // In the equatorial plane the WGS84 surface is exactly a circle of radius a.
    // Form c as a difference of squares to avoid losing the small 10 m offset.
    let b = origin.dot(direction);
    let c = 10.0 * (2.0 * WGS84_A_M + 10.0) + 1_000_000.0;
    let expected_far_distance = -b + (b * b - c).sqrt();
    let far = origin + direction * expected_far_distance;
    assert!(far.y.atan2(far.x).to_degrees() > 0.1);
    let surface = scene.intersect(Ray { origin, direction }).unwrap();
    assert!(scene.intersects_any(Ray { origin, direction }));
    assert_eq!(surface.kind, SurfaceKind::ReferenceEllipsoid);
    close(surface.hit.distance_m, expected_far_distance, 2.0e-5);
}

#[test]
fn mercator_imagery_uses_projected_rows_and_outer_pixel_edges() {
    let mut rgba = Vec::new();
    for row in 0..4 {
        for column in 0..4 {
            rgba.extend_from_slice(&[column, row, 17, 255]);
        }
    }
    let limit = std::f64::consts::PI.sinh().atan().to_degrees();
    let mercator = PatchTextureView {
        texture: TextureView {
            rgba: &rgba,
            width: 4,
            height: 4,
        },
        projection: TextureProjection::WebMercator,
        west_deg: -180.0,
        south_deg: -limit,
        east_deg: 180.0,
        north_deg: limit,
    };
    // Latitude atan(sinh(pi/2)) is exactly one quarter down a Mercator world.
    let latitude = (std::f64::consts::PI / 2.0).sinh().atan().to_degrees();
    let uv = mercator.uv(geo(latitude, 45.0, 0.0)).unwrap();
    close(uv[0], 0.625, 1.0e-15);
    close(uv[1], 0.25, 1.0e-15);
    let geographic = PatchTextureView {
        projection: TextureProjection::Geographic,
        ..mercator
    };
    assert!((geographic.uv(geo(latitude, 45.0, 0.0)).unwrap()[1] - 0.25).abs() > 0.1);
    for row in 0..4 {
        for column in 0..4 {
            let u = (f64::from(column) + 0.5) / 4.0;
            let v = (f64::from(row) + 0.5) / 4.0;
            let latitude = (std::f64::consts::PI * (1.0 - 2.0 * v))
                .sinh()
                .atan()
                .to_degrees();
            let location = geo(latitude, u * 360.0 - 180.0, 0.0);
            assert_eq!(mercator.sample(location), Some([column, row, 17]));
        }
    }
    assert_eq!(mercator.sample(geo(limit, -180.0, 0.0)), Some([0, 0, 17]));
    assert_eq!(mercator.sample(geo(-limit, 180.0, 0.0)), Some([3, 3, 17]));
    assert!(mercator.uv(geo(89.0, 0.0, 0.0)).is_none());
    assert!(
        PatchTextureView {
            north_deg: 90.0,
            ..mercator
        }
        .uv(geo(0.0, 0.0, 0.0))
        .is_none()
    );
}

#[test]
fn local_color_filter_is_bilinear_between_pixel_centers_with_clamped_edges() {
    let rgba = [
        0, 0, 0, 255, 100, 40, 20, 255, 20, 120, 80, 255, 200, 240, 160, 255,
    ];
    let texture = PatchTextureView {
        texture: TextureView {
            rgba: &rgba,
            width: 2,
            height: 2,
        },
        projection: TextureProjection::Geographic,
        west_deg: 0.0,
        south_deg: 0.0,
        east_deg: 1.0,
        north_deg: 1.0,
    };
    assert_eq!(texture.sample(geo(0.5, 0.5, 0.0)), Some([80, 100, 65]));
    // Fractional pixel coordinates x=1/4,y=3/4: weights 3/16,1/16,9/16,3/16.
    assert_eq!(texture.sample(geo(0.375, 0.375, 0.0)), Some([55, 115, 76]));
    assert_eq!(texture.sample(geo(1.0, 0.0, 0.0)), Some([0, 0, 0]));
    assert_eq!(texture.sample(geo(0.0, 1.0, 0.0)), Some([200, 240, 160]));
    for longitude in [0.5 - 1.0e-9, 0.5 + 1.0e-9] {
        assert_eq!(
            texture.sample(geo(0.5, longitude, 0.0)),
            Some([80, 100, 65])
        );
    }
}

#[test]
fn transparent_pixels_do_not_bleed_color_into_alpha_weighted_imagery() {
    let rgba = [
        0, 180, 0, 255, 255, 0, 255, 0, 255, 0, 255, 0, 255, 0, 255, 0,
    ];
    let texture = PatchTextureView {
        texture: TextureView {
            rgba: &rgba,
            width: 2,
            height: 2,
        },
        projection: TextureProjection::Geographic,
        west_deg: 0.0,
        south_deg: 0.0,
        east_deg: 1.0,
        north_deg: 1.0,
    };
    assert_eq!(
        texture.sample_rgba(geo(0.5, 0.5, 0.0)),
        Some([0, 180, 0, 64])
    );
    assert_eq!(texture.sample(geo(0.5, 0.5, 0.0)), Some([0, 180, 0]));
    assert_eq!(texture.sample_rgba(geo(0.25, 0.75, 0.0)), None);
    let partial = [
        255, 0, 0, 255, 0, 0, 255, 85, 255, 255, 0, 0, 255, 255, 0, 0,
    ];
    let weighted = PatchTextureView {
        texture: TextureView {
            rgba: &partial,
            width: 2,
            height: 2,
        },
        ..texture
    };
    // Equal bilinear weights; red has three times blue's valid coverage.
    assert_eq!(
        weighted.sample_rgba(geo(0.5, 0.5, 0.0)),
        Some([191, 0, 64, 85])
    );
}

#[test]
fn transparent_local_imagery_blends_fallback_without_changing_the_surface() {
    let scene = TerrainScene::new(vec![plane_patch(WGS84_A_M - 500.0)]);
    let frame = CameraFrame::new(geo(0.0, 0.0, 1000.0), 0.0, -90.0);
    let fallback_pixels = [0, 255, 0, 255];
    let fallback = TextureView {
        rgba: &fallback_pixels,
        width: 1,
        height: 1,
    };
    let render = |rgba: &[u8; 4]| {
        let local = PatchTextureView {
            texture: TextureView {
                rgba,
                width: 1,
                height: 1,
            },
            projection: TextureProjection::Geographic,
            west_deg: -0.1,
            south_deg: -0.1,
            east_deg: 0.1,
            north_deg: 0.1,
        };
        scene.render_pixel(
            frame,
            Lens::default(),
            0,
            0,
            1,
            1,
            [100.0, 100.0],
            Some(fallback),
            &[Some(local)],
        )
    };
    assert_eq!(render(&[255, 0, 255, 0]), render(&[0, 255, 0, 255]));
    assert_eq!(render(&[255, 0, 0, 128]), render(&[128, 127, 0, 255]));
    let hit = scene.intersect(frame.center_ray()).unwrap();
    assert_eq!(hit.kind, SurfaceKind::Terrain(0));
    close(hit.hit.distance_m, 1500.0, 3.0e-9);
}

#[test]
fn mesh_constructor_rejects_chords_below_the_inverse_height_domain() {
    // Although every post is in range, Cartesian interpolation between posts
    // at the minimum height dips beneath that minimum and must be rejected.
    assert!(matches!(
        TerrainPatch::from_grid(2, 2, -0.01, 0.01, 0.02, 0.02, vec![-10_000.0; 4]),
        Err(TerrainError::InvalidGrid)
    ));
    let patch = TerrainPatch::from_grid(2, 2, -0.01, 0.01, 0.02, 0.02, vec![-9000.0; 4]).unwrap();
    let angle = 0.01_f64.to_radians();
    let prime_vertical = WGS84_A_M / (1.0 - WGS84_E2 * angle.sin().powi(2)).sqrt();
    let plane_x = (prime_vertical - 9000.0) * angle.cos().powi(2);
    let hit = patch
        .intersect(Ray {
            origin: Vec3d::new(WGS84_A_M, 0.0, 0.0),
            direction: Vec3d::new(-1.0, 0.0, 0.0),
        })
        .unwrap();
    close(hit.distance_m, WGS84_A_M - plane_x, 3.0e-9);
    assert!(hit.geodetic.height_m < -9000.0);
    assert!(hit.geodetic.height_m > -10_000.0);
}

#[test]
fn terrain_binary_has_explicit_endianness_and_rejects_partial_or_trailing_data() {
    let mut bytes = b"AETERR01".to_vec();
    bytes.extend_from_slice(&2_u32.to_le_bytes());
    bytes.extend_from_slice(&2_u32.to_le_bytes());
    for number in [-0.01_f64, 0.01, 0.02, 0.02] {
        bytes.extend_from_slice(&number.to_le_bytes());
    }
    let plane_x = WGS84_A_M + 120.0;
    for latitude in [0.01, -0.01] {
        for longitude in [-0.01, 0.01] {
            bytes.extend_from_slice(&plane_height(latitude, longitude, plane_x).to_le_bytes());
        }
    }
    let patch = TerrainPatch::from_bytes(&bytes).unwrap();
    assert_eq!(patch.bounds(), [-0.01, -0.01, 0.01, 0.01]);
    let hit = patch
        .intersect(Ray {
            origin: Vec3d::new(plane_x + 100.0, 0.0, 0.0),
            direction: Vec3d::new(-1.0, 0.0, 0.0),
        })
        .unwrap();
    close(hit.distance_m, 100.0, 3.0e-9);
    assert!(matches!(
        TerrainPatch::from_bytes(&bytes[..bytes.len() - 1]),
        Err(TerrainError::InvalidFormat)
    ));
    bytes.push(0);
    assert!(matches!(
        TerrainPatch::from_bytes(&bytes),
        Err(TerrainError::InvalidFormat)
    ));
}

#[test]
fn archived_terrain_eye_ranges_use_the_imported_mesh() {
    let fuji =
        TerrainPatch::from_bytes(include_bytes!("../../../assets/terrain/fuji.aet")).unwrap();
    let tokyo =
        TerrainPatch::from_bytes(include_bytes!("../../../assets/terrain/tokyo.aet")).unwrap();
    let houston =
        TerrainPatch::from_bytes(include_bytes!("../../../assets/terrain/houston.aet")).unwrap();
    let galveston =
        TerrainPatch::from_bytes(include_bytes!("../../../assets/terrain/galveston.aet")).unwrap();
    assert_eq!(fuji.vertex_count(), 265 * 217);
    assert_eq!(tokyo.vertex_count(), 265 * 216);
    assert_eq!(houston.vertex_count(), 249 * 217);
    assert_eq!(galveston.vertex_count(), 247 * 216);
    let scene = TerrainScene::new(vec![fuji, tokyo, houston, galveston]);
    for (patch_index, patch) in scene.patches().iter().enumerate() {
        let [west, south, east, north] = patch.bounds();
        let location = geo((south + north) * 0.5, (west + east) * 0.5, 0.0);
        let ground = scene.ground(location).unwrap();
        assert_eq!(ground.kind, SurfaceKind::Terrain(patch_index));
        for height in [0.0, 1200.0] {
            let mut observer = Observer::new(
                ground
                    .hit
                    .geodetic
                    .with_height(ground.hit.geodetic.height_m + height)
                    .unwrap(),
            );
            // Archived DSM fixtures can have negative ellipsoidal heights.
            observer.feet = ground
                .hit
                .geodetic
                .with_height(ground.hit.geodetic.height_m + height)
                .unwrap();
            observer.pitch_deg = -90.0;
            let downward = CameraFrame::new(observer.eye_geodetic(), 0.0, -90.0).center_ray();
            let range = scene.intersect(downward).unwrap();
            assert_eq!(range.kind, ground.kind);
            close(
                range.hit.distance_m,
                observer.feet.height_m - ground.hit.geodetic.height_m + observer.eye_height_m,
                2.0e-7,
            );
            assert_eq!(
                scene.intersect(observer.frame().center_ray()).unwrap().kind,
                ground.kind
            );
        }
    }
    assert_eq!(
        scene.ground(geo(-35.36, -41.27, 0.0)).unwrap().kind,
        SurfaceKind::ReferenceEllipsoid
    );
}

#[test]
fn coastal_source_points_preserve_negative_ground_and_eye_heights() {
    let houston =
        TerrainPatch::from_bytes(include_bytes!("../../../assets/terrain/houston.aet")).unwrap();
    let galveston =
        TerrainPatch::from_bytes(include_bytes!("../../../assets/terrain/galveston.aet")).unwrap();
    let scene = TerrainScene::new(vec![houston, galveston]);
    for (index, latitude, longitude) in [(0, 29.76328, -95.36327), (1, 29.30135, -94.7977)] {
        let location = geo(latitude, longitude, 100.0);
        let ground = scene.ground(location).unwrap();
        assert_eq!(ground.kind, SurfaceKind::Terrain(index));
        assert!(ground.hit.geodetic.height_m < -2.0);
        assert_eq!(ground.hit.geodetic.lat_deg, latitude);
        assert_eq!(ground.hit.geodetic.lon_deg, longitude);
        let mut observer = Observer::new(location);
        scene.place_on_ground(&mut observer, location).unwrap();
        observer.set_eye_height(1.75);
        assert!(observer.eye_geodetic().height_m < 0.0);
        let down = CameraFrame::new(observer.eye_geodetic(), 0.0, -90.0).center_ray();
        let measured = scene.intersect(down).unwrap();
        assert_eq!(measured.kind, ground.kind);
        close(measured.hit.distance_m, 1.75, 2.0e-8);
        let precise = geo(latitude, longitude, ground.hit.geodetic.height_m + 0.25);
        scene.try_teleport(&mut observer, precise).unwrap();
        assert_eq!(observer.feet, precise);
        observer.pitch_deg = -90.0;
        observer.speed_mps = 50_000_000.0;
        scene.fly(&mut observer, 1.0, 0.0, 0.0, 0.25, true);
        close(
            observer.feet.height_m,
            ground.hit.geodetic.height_m + 0.00001,
            3.0e-8,
        );
    }
}

#[test]
fn boolean_scene_query_preserves_canonical_hit_existence_across_masks_and_extreme_rays() {
    let scenes = [
        TerrainScene::new(vec![]),
        TerrainScene::new(vec![plane_patch(WGS84_A_M + 120.0)]),
        TerrainScene::new(vec![plane_patch(WGS84_A_M - 500.0)]),
        TerrainScene::new(vec![
            TerrainPatch::from_bytes(include_bytes!("../../../assets/terrain/fuji.aet")).unwrap(),
            TerrainPatch::from_bytes(include_bytes!("../../../assets/terrain/tokyo.aet")).unwrap(),
            TerrainPatch::from_bytes(include_bytes!("../../../assets/terrain/houston.aet"))
                .unwrap(),
            TerrainPatch::from_bytes(include_bytes!("../../../assets/terrain/galveston.aet"))
                .unwrap(),
        ]),
    ];
    for scene in &scenes {
        for ray in [
            Ray {
                origin: Vec3d::new(WGS84_A_M + 10.0, 0.0, 0.0),
                direction: Vec3d::new(1.0, 0.0, 0.0),
            },
            Ray {
                origin: Vec3d::new(WGS84_A_M + 10.0, -1000.0, 0.0),
                direction: Vec3d::new(-0.005, 1.0, 0.0),
            },
            Ray {
                origin: Vec3d::new(WGS84_A_M, -1000.0, 0.0),
                direction: Vec3d::new(0.0, 1.0, 0.0),
            },
            Ray {
                origin: Vec3d::ZERO,
                direction: Vec3d::new(1.0, 0.0, 0.0),
            },
            Ray {
                origin: Vec3d::new(WGS84_A_M + 1000.0, 0.0, 0.0),
                direction: Vec3d::ZERO,
            },
            Ray {
                origin: Vec3d::new(f64::NAN, 0.0, 0.0),
                direction: Vec3d::new(-1.0, 0.0, 0.0),
            },
            Ray {
                origin: Vec3d::new(WGS84_A_M, 0.0, 0.0),
                direction: Vec3d::new(f64::INFINITY, 0.0, 0.0),
            },
        ] {
            assert_eq!(
                scene.intersects_any(ray),
                scene.intersect(ray).is_some(),
                "{ray:?}"
            );
        }
        for (lat, lon) in [
            (0.0, 0.0),
            (29.76328, -95.36327),
            (29.30135, -94.7977),
            (35.36, 138.73),
            (90.0, 179.0),
        ] {
            let ground = scene.ground(geo(lat, lon, 0.0)).unwrap();
            for height in [ground.hit.geodetic.height_m + 1.72, 100_000.0] {
                let frame = CameraFrame::with_roll(geo(lat, lon, height), 45.0, -10.0, 31.0);
                for projection in [Projection::Rectilinear, Projection::EquidistantFisheye] {
                    let lens = Lens::new(projection, 140.0);
                    for y in -6..=6 {
                        for x in -8..=8 {
                            let Some(direction) =
                                lens.ray(frame, f64::from(x) / 8.0, f64::from(y) / 6.0, 16.0 / 9.0)
                            else {
                                continue;
                            };
                            let scale = match (x + y + 14) % 3 {
                                0 => 1e-200,
                                1 => 1.0,
                                _ => 1e200,
                            };
                            let ray = Ray {
                                origin: frame.origin,
                                direction: direction * scale,
                            };
                            assert_eq!(
                                scene.intersects_any(ray),
                                scene.intersect(ray).is_some(),
                                "{ray:?}"
                            );
                        }
                    }
                }
            }
        }
    }
    let empty = &scenes[0];
    assert!(empty.intersects_any(Ray {
        origin: Vec3d::new(WGS84_A_M + 10.0, 0.0, 0.0),
        direction: Vec3d::new(-1.0, 0.0, 0.0)
    }));
    assert!(!empty.intersects_any(Ray {
        origin: Vec3d::new(WGS84_A_M + 10.0, 0.0, 0.0),
        direction: Vec3d::new(1.0, 0.0, 0.0)
    }));
}
